use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


#[derive(rig::Embed, serde::Serialize, Clone)]
struct WordDefinition {
    id: String,
    word: String,
    #[embed]
    definitions: Vec<String>,
}


#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let client = OpenAI::from_env()?;
    let embedding_model = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);


    // Ingestion: embed the documents and load them into an in-memory store.
    let embeddings = EmbeddingsBuilder::new(embedding_model.clone())
        .documents(vec![
            WordDefinition {
                id: "doc0".into(),
                word: "flurbo".into(),
                definitions: vec!["A green alien that lives on cold planets.".into()],
            },
            WordDefinition {
                id: "doc1".into(),
                word: "glarb-glarb".into(),
                definitions: vec!["An ancient farming tool from planet Jiro.".into()],
            },
        ])?
        .build()
        .await?;
    let index = InMemoryVectorStore::from_documents(embeddings).index(embedding_model);


    // Retrieval: the agent fetches the best match for every prompt.
    let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
        .preamble("You are a dictionary assistant. Use the definitions provided as context.")
        .dynamic_context(1, index)
        .build();


    let answer = agent.prompt("What does \"glarb-glarb\" mean?").await?.output();
    println!("{answer}");
    Ok(())
}

let req = VectorSearchRequest::builder()
    .query("What type of money can I use in a fictional universe?")
    .samples(2)
    .threshold(0.3) // optional: drop weak matches
    .build();


for result in index.top_n::<WordDefinition>(req).await? {
    println!("score={:.2} id={} word={}", result.score, result.id, result.document.word);
}

use rig::vector_store::request::{Filter, SearchFilter};


let req = VectorSearchRequest::builder()
    .query("cold planets")
    .samples(5)
    .filter(Filter::eq("word", json!("flurbo")))
    .build();
let results = index.top_n::<serde_json::Value>(req).await?;

use rig::operation::RerankRequest;
use rig::providers::voyageai::{self, VoyageAi};


// Requires VOYAGE_API_KEY.
let reranker = VoyageAi::from_env()?.rerank(voyageai::RERANK_2_5);


let response = reranker
    .call(RerankRequest {
        query: "Which animal lives on cold planets?".into(),
        documents: vec![
            "A glarb-glarb is an ancient farming tool.".into(),
            "A flurbo is a green alien that lives on cold planets.".into(),
        ],
    })
    .await?;


for result in response.results {
    println!("#{} scored {:.3}", result.index, result.relevance_score);
}
